const getTeamMemberForAccountUser = async (
	accountIds: string[],
	userData: any,
	userId: string,
	authEmail?: string | null,
): Promise<TeamMemberAccess | null> => {
	const normalizedEmail = String(userData?.email || authEmail || '')
		.trim()
		.toLowerCase();
	const teamMemberId = String(userData?.teamMemberId || '').trim();

	for (const accountId of accountIds) {
		try {
			let membersSnapshot;
			if (teamMemberId) {
				const memberDoc = await getDoc(doc(db, 'teamMembers', teamMemberId));
				if (memberDoc.exists()) {
					const member = docToData(memberDoc) as TeamMemberAccess;
					if (member?.accountId === accountId || !member?.accountId) {
						return member;
					}
				}
			}

			if (normalizedEmail) {
				const membersQuery = query(
					collection(db, 'teamMembers'),
					where('accountId', '==', accountId),
					where('email', '==', normalizedEmail),
				);
				membersSnapshot = await getDocs(membersQuery);
				if (!membersSnapshot.empty) {
					return docToData(membersSnapshot.docs[0]) as TeamMemberAccess;
				}

				const accountMembersQuery = query(
					collection(db, 'teamMembers'),
					where('accountId', '==', accountId),
				);
				membersSnapshot = await getDocs(accountMembersQuery);
				const emailMatch = membersSnapshot.docs
					.map((memberDoc) => docToData(memberDoc) as TeamMemberAccess)
					.find(
						(member) =>
							String(member?.email || '').trim().toLowerCase() ===
							normalizedEmail,
					);
				if (emailMatch) {
					return emailMatch;
				}
			}

			const userAccountQuery = query(
				collection(db, 'teamMembers'),
				where('accountId', '==', accountId),
				where('userAccountId', '==', userId),
			);
			membersSnapshot = await getDocs(userAccountQuery);
			if (!membersSnapshot.empty) {
				return docToData(membersSnapshot.docs[0]) as TeamMemberAccess;
			}
		} catch (error) {
			console.warn('Could not resolve team member access:', error);
		}
	}

	return null;
};

type TeamMemberAccess = {
	id?: string;
	accountId?: string;
	email?: string;
	userAccountId?: string;
	linkedProperties?: string[];
};

const isTeamMemberScopedProfile = (
	userData: any,
	teamMember: TeamMemberAccess | null,
): boolean => {
	if (
		String(userData?.subscription?.promoCode || '')
			.trim()
			.toUpperCase()
			.startsWith('TEAM-')
	) {
		return true;
	}

	if (userData?.isAccountOwner === true) {
		return false;
	}

	return userData?.isTeamMemberAccount === true || !!teamMember;
};

const getLinkedPropertyIdSet = (teamMember: TeamMemberAccess | null) =>
	new Set((teamMember?.linkedProperties || []).filter(Boolean));

const scopePropertiesToTeamMember = (
	properties: Property[],
	teamMember: TeamMemberAccess | null,
): Property[] => {
	const linkedPropertyIds = getLinkedPropertyIdSet(teamMember);
	if (linkedPropertyIds.size === 0) {
		return [];
	}

	return properties.filter((property) => linkedPropertyIds.has(property.id));
};

const scopeGroupsToTeamMember = async (
	groups: PropertyGroup[],
	teamMember: TeamMemberAccess | null,
	targetUserId: string,
): Promise<PropertyGroup[]> => {
	const linkedPropertyIds = getLinkedPropertyIdSet(teamMember);
	if (linkedPropertyIds.size === 0) {
		return [];
	}

	const scopedGroups = groups
		.map((group) => ({
			...group,
			properties:
				group.properties?.filter((property) =>
					linkedPropertyIds.has(property.id),
				) || [],
		}))
		.filter((group) => group.properties && group.properties.length > 0);

	if (scopedGroups.length > 0) {
		return scopedGroups;
	}

	const assignedProperties = await fetchPropertiesByIds(
		Array.from(linkedPropertyIds),
	);
	if (assignedProperties.length === 0) {
		return [];
	}

	return [
		{
			id: `team-${targetUserId}-assigned-properties`,
			name: 'Assigned Properties',
			userId: targetUserId,
			accountId: targetUserId,
			properties: assignedProperties,
			createdAt: new Date().toISOString(),
			updatedAt: new Date().toISOString(),
		},
	];
};

const upsertPropertyGroupMembership = async (params: {
	accountId: string;
	groupId: string;
	propertyId: string;
	sortOrder?: number;
}) => {
	const { accountId, groupId, propertyId, sortOrder = Date.now() } = params;
	const now = new Date().toISOString();

	const membershipQuery = query(
		collection(db, PROPERTY_GROUP_MEMBERSHIPS_COLLECTION),
		where('propertyId', '==', propertyId),
		where('accountId', '==', accountId),
	);
	const membershipSnapshot = await getDocs(membershipQuery);
	const existingMembershipDoc = membershipSnapshot.docs[0];

	if (existingMembershipDoc) {
		await updateDoc(existingMembershipDoc.ref, {
			groupId,
			sortOrder,
			updatedAt: now,
		});
		return;
	}

	await addDoc(collection(db, PROPERTY_GROUP_MEMBERSHIPS_COLLECTION), {
		accountId,
		groupId,
		propertyId,
		sortOrder,
		createdAt: now,
		updatedAt: now,
	});
};

const deletePropertyGroupMemberships = async (
	propertyId: string,
	accountId?: string,
) => {
	let membershipQuery = query(
		collection(db, PROPERTY_GROUP_MEMBERSHIPS_COLLECTION),
		where('propertyId', '==', propertyId),
	);

	if (accountId) {
		membershipQuery = query(
			collection(db, PROPERTY_GROUP_MEMBERSHIPS_COLLECTION),
			where('propertyId', '==', propertyId),
			where('accountId', '==', accountId),
		);
	}

	const membershipSnapshot = await getDocs(membershipQuery);
	for (const membershipDoc of membershipSnapshot.docs) {
		await deleteDoc(membershipDoc.ref);
	}
};

const propertySlice = apiSlice.injectEndpoints({
	endpoints: (builder) => ({
		// Property endpoints
		// Property Group endpoints
		getPropertyGroups: builder.query<PropertyGroup[], void>({
			async queryFn() {
				try {
					const currentUser = auth.currentUser;
					if (!currentUser) {
						return { error: 'User not authenticated' };
					}
					const userId = currentUser.uid;
					// Get user's email for shared properties lookup
					const userDocRef = doc(db, 'users', userId);
					const userDoc = await getDoc(userDocRef);
					const userData = userDoc.data();
					const userEmail = userData?.email;

					if (
						String(userData?.role || '').trim().toLowerCase() === 'tenant'
					) {
						try {
							const syncTenantAccess = httpsCallable<
								Record<string, never>,
								{ success: boolean }
							>(functions, 'syncTenantAccessFromInvites');
							await syncTenantAccess({});
						} catch (syncError) {
							console.warn('Tenant access sync in property query skipped:', syncError);
						}
					}

					const accessibleAccountIds = await resolveAccessibleAccountIds();
					const targetUserId = await resolveTargetUserId();
					const currentTeamMember = await getTeamMemberForAccountUser(
						accessibleAccountIds,
						userData,
						userId,
						currentUser.email,
					);
					const isTeamMemberScoped = isTeamMemberScopedProfile(
						userData,
						currentTeamMember,
					);

					// Get property groups
					const groupDocs = [] as any[];
					for (const accountId of accessibleAccountIds) {
						const groupsQuery = query(
							collection(db, 'propertyGroups'),
							where('accountId', '==', accountId),
						);
						const querySnapshot = await getDocs(groupsQuery);
						groupDocs.push(...querySnapshot.docs);
					}

					const uniqueGroupDocs = Array.from(
						new Map(
							groupDocs.map((groupDoc) => [groupDoc.id, groupDoc]),
						).values(),
					);

					const groups = uniqueGroupDocs
						.map((doc) => docToData(doc) as PropertyGroup)
						.filter(Boolean) as PropertyGroup[];

					const memberships: PropertyGroupMembership[] = [];
					for (const accountId of accessibleAccountIds) {
						try {
							const membershipsQuery = query(
								collection(db, PROPERTY_GROUP_MEMBERSHIPS_COLLECTION),
								where('accountId', '==', accountId),
							);
							const membershipsSnapshot = await getDocs(membershipsQuery);
							const membershipBatch = membershipsSnapshot.docs
								.map(
									(doc) => docToData(doc) as PropertyGroupMembership,
								)
								.filter(Boolean) as PropertyGroupMembership[];
							memberships.push(...membershipBatch);
						} catch (_membershipError) {
							// Graceful fallback for environments where propertyGroupMemberships
							// rules have not been deployed yet.
						}
					}

					const membershipsByGroupId = new Map<string, PropertyGroupMembership[]>();
					for (const membership of memberships) {
						if (!membership.groupId || !membership.propertyId) {
							continue;
						}

						const current = membershipsByGroupId.get(membership.groupId) || [];
						current.push(membership);
						membershipsByGroupId.set(membership.groupId, current);
					}

					for (const [groupId, groupMemberships] of membershipsByGroupId.entries()) {
						groupMemberships.sort((a, b) => {
							const aOrder = Number.isFinite(a.sortOrder)
								? a.sortOrder
								: Number.MAX_SAFE_INTEGER;
							const bOrder = Number.isFinite(b.sortOrder)
								? b.sortOrder
								: Number.MAX_SAFE_INTEGER;
							return aOrder - bOrder;
						});
						membershipsByGroupId.set(groupId, groupMemberships);
					}

					const membershipPropertyIds = Array.from(
						new Set(memberships.map((membership) => membership.propertyId).filter(Boolean)),
					);
					const membershipProperties = await fetchPropertiesByIds(membershipPropertyIds);
					const propertyById = new Map(
						membershipProperties.map((property) => [property.id, property]),
					);

					const normalizedUserEmail = String(userEmail || '').trim().toLowerCase();

					let shares: PropertyShare[] = [];
					let coOwnerSharedProperties: Property[] = [];
					let regularSharedProperties: Property[] = [];
					try {
						shares = await getReceivedPropertySharesForUser(
							userId,
							userEmail,
							currentUser.email,
						);

						const coOwnerShares = shares.filter(
							(share) => share.permission === 'co-owner',
						);
						const regularShares = shares.filter(
							(share) => share.permission !== 'co-owner',
						);

						coOwnerSharedProperties = await fetchPropertiesByIds(
							coOwnerShares.map((share) => share.propertyId),
						);
						regularSharedProperties = await fetchPropertiesByIds(
							regularShares.map((share) => share.propertyId),
						);
					} catch (sharesError) {
						console.warn('Could not fetch shared property links:', sharesError);
					}

					let tenantInvitePropertyIds: string[] = [];
					if (normalizedUserEmail) {
						try {
							const tenantInvitesQuery = query(
								collection(db, 'tenantInvitationCodes'),
								where('tenantEmail', '==', normalizedUserEmail),
							);
							const tenantInvitesSnapshot = await getDocs(tenantInvitesQuery);
							const invitePropertyIds = tenantInvitesSnapshot.docs
								.map((inviteDoc) => inviteDoc.data() as any)
								.filter((invite) => {
									const status = String(invite?.status || '').trim().toLowerCase();
									return (
										(status === 'active' || status === 'redeemed') &&
										typeof invite?.propertyId === 'string' &&
										invite.propertyId.trim().length > 0
									);
								})
								.map((invite) => String(invite.propertyId).trim());

							tenantInvitePropertyIds = Array.from(new Set(invitePropertyIds));
						} catch (tenantInviteError) {
							console.warn(
								'Could not fetch tenant invitation code assignments:',
								tenantInviteError,
							);
						}
					}

					// Fetch properties for each group
					const groupsWithProperties: PropertyGroup[] = await Promise.all(
						groups.map(async (group) => {
							const isSharedGroup =
								group.name?.toLowerCase() === 'shared properties';
							const isMyPropertiesGroup =
								group.name?.toLowerCase() === 'my properties';

							const groupMemberships = membershipsByGroupId.get(group.id) || [];
							let ownedProperties = groupMemberships
								.map((membership) => propertyById.get(membership.propertyId))
								.filter(Boolean) as Property[];

							// Legacy fallback for records that still only rely on property.groupId
							if (ownedProperties.length === 0) {
								const legacyQueryClauses = [where('groupId', '==', group.id)];
								if (group.accountId) {
									legacyQueryClauses.push(where('accountId', '==', group.accountId));
								}
								const propertiesQuery = query(
									collection(db, 'properties'),
									...legacyQueryClauses,
								);
								const propertiesSnapshot = await getDocs(propertiesQuery);
								ownedProperties = propertiesSnapshot.docs
									.map((doc) => docToData(doc) as Property)
									.filter(Boolean) as Property[];
							}

							let sharedProperties: Property[] = [];
							if (shares.length > 0) {
								if (isMyPropertiesGroup) {
									sharedProperties = [...coOwnerSharedProperties];
								} else if (isSharedGroup) {
									sharedProperties = [...regularSharedProperties];
								}
							}

							const allProperties = [...ownedProperties, ...sharedProperties];
							const uniqueProperties = Array.from(
								new Map(allProperties.map((p) => [p.id, p])).values(),
							);

							return {
								...group,
								properties: uniqueProperties,
							};
						}),
					);

					// Check if we need to create a "Shared Properties" group
					const hasSharedPropertiesGroup = groupsWithProperties.some(
						(group) => group.name?.toLowerCase() === 'shared properties',
					);

					let finalGroups: PropertyGroup[] = [...groupsWithProperties];

					// If no Shared Properties group exists, check if user has shared properties
					if (!hasSharedPropertiesGroup) {
						const receivedShares = await getReceivedPropertySharesForUser(
							userId,
							userEmail,
							currentUser.email,
						);
						if (receivedShares.length > 0) {
							// User has shared properties, create the group
							try {
								const sharedGroupData = {
									name: 'Shared Properties',
									userId: targetUserId,
									accountId: targetUserId,
									properties: [],
									createdAt: new Date().toISOString(),
									updatedAt: new Date().toISOString(),
								};
								const sharedGroupRef = await addDoc(
									collection(db, 'propertyGroups'),
									sharedGroupData,
								);
								finalGroups.push({
									id: sharedGroupRef.id,
									...sharedGroupData,
								});
								// Note: Properties will be loaded on next query refresh
							} catch (error) {
								console.error('Error creating Shared Properties group:', error);
							}
						}
					}

					if (String(userData?.role || '').trim().toLowerCase() === 'tenant') {
						const tenantScopedIds = new Set<string>(tenantInvitePropertyIds);

						if (normalizedUserEmail) {
							for (const group of finalGroups) {
								for (const property of group.properties || []) {
									const tenants = (((property as any).tenants as any[]) || []).filter(
										Boolean,
									);
									const hasTenantMatch = tenants.some(
										(tenant) =>
											String(tenant?.email || '').trim().toLowerCase() ===
											normalizedUserEmail,
									);
									if (hasTenantMatch && property?.id) {
										tenantScopedIds.add(property.id);
									}
								}
							}
						}

						let tenantAssignedProperties = finalGroups
							.flatMap((group) => group.properties || [])
							.filter((property) => property?.id && tenantScopedIds.has(property.id));

						if (tenantAssignedProperties.length === 0 && tenantScopedIds.size > 0) {
							tenantAssignedProperties = await fetchPropertiesByIds(
								Array.from(tenantScopedIds),
							);
						}

						const uniqueTenantProperties = Array.from(
							new Map(
								tenantAssignedProperties.map((property) => [property.id, property]),
							).values(),
						);

						if (uniqueTenantProperties.length > 0) {
							const myPropertiesGroup = finalGroups.find(
								(group) => group.name?.toLowerCase() === 'my properties',
							);

							if (myPropertiesGroup) {
								myPropertiesGroup.properties = uniqueTenantProperties;
								finalGroups = finalGroups
									.filter((group) => group.id === myPropertiesGroup.id)
									.map((group) => ({ ...group }));
							} else {
								finalGroups = [
									{
										id: `tenant-${targetUserId}-assigned-properties`,
										name: 'My Properties',
										userId: targetUserId,
										accountId: targetUserId,
										properties: uniqueTenantProperties,
										createdAt: new Date().toISOString(),
										updatedAt: new Date().toISOString(),
									},
								];
							}
						} else {
							finalGroups = [];
						}
					}

					const isTenantUser =
						String(userData?.role || '').trim().toLowerCase() === 'tenant';

					if (isTeamMemberScoped && !isTenantUser) {
						finalGroups = await scopeGroupsToTeamMember(
							finalGroups,
							currentTeamMember,
							targetUserId,
						);
					}

					// Final fallback: if groups are missing but properties exist, expose a virtual group
					if (finalGroups.length === 0 && !isTenantUser && !isTeamMemberScoped) {
						const fallbackProperties: Property[] = [];
						for (const accountId of accessibleAccountIds) {
							const accountPropertiesQuery = query(
								collection(db, 'properties'),
								where('accountId', '==', accountId),
							);
							const accountPropertiesSnapshot = await getDocs(
								accountPropertiesQuery,
							);
							const batch = accountPropertiesSnapshot.docs
								.map((doc) => docToData(doc) as Property)
								.filter(Boolean) as Property[];
							fallbackProperties.push(...batch);
						}

						const uniqueFallbackProperties = Array.from(
							new Map(
								fallbackProperties.map((property) => [property.id, property]),
							).values(),
						) as Property[];

						if (uniqueFallbackProperties.length > 0) {
							finalGroups.push({
								id: `virtual-${targetUserId}-my-properties`,
								name: 'My Properties',
								userId: targetUserId,
								accountId: targetUserId,
								properties: uniqueFallbackProperties,
								createdAt: new Date().toISOString(),
								updatedAt: new Date().toISOString(),
							});
						}
					}

					return { data: finalGroups };
				} catch (error: any) {
					return { error: error.message };
				}
			},
			providesTags: ['PropertyGroups', 'Properties'],
		}),

		getPropertyGroup: builder.query<PropertyGroup, string>({
			async queryFn(groupId: string) {
				try {
					const docRef = doc(db, 'propertyGroups', groupId);
					const docSnapshot = await getDoc(docRef);
					const data = docToData(docSnapshot) as PropertyGroup;
					return { data };
				} catch (error: any) {
					return { error: error.message };
				}
			},
			providesTags: ['PropertyGroups'],
		}),

		createPropertyGroup: builder.mutation<
			PropertyGroup,
			Omit<PropertyGroup, 'id'>
		>({
			async queryFn(newGroup) {
				try {
					const currentUser = auth.currentUser;
					if (!currentUser) {
						return { error: 'User not authenticated' };
					}
					const targetUserId = await resolveTargetUserId();
					const userDoc = await getDoc(doc(db, 'users', currentUser.uid));
					const userData = userDoc.data() || {};
					const currentTeamMember = await getTeamMemberForAccountUser(
						[targetUserId],
						userData,
						currentUser.uid,
					);

					if (isTeamMemberScopedProfile(userData, currentTeamMember)) {
						return {
							error:
								'Team member accounts cannot create property groups. Ask the account owner to manage property groups.',
						};
					}

					const docRef = await addDoc(collection(db, 'propertyGroups'), {
						...newGroup,
						userId: targetUserId, // Ensure property group is owned by account owner
						accountId: targetUserId,
						createdAt: new Date().toISOString(),
						updatedAt: new Date().toISOString(),
					});
					return {
						data: {
							id: docRef.id,
							...newGroup,
							userId: targetUserId,
							accountId: targetUserId,
						} as PropertyGroup,
					};
				} catch (error: any) {
					return { error: error.message };
				}
			},
			invalidatesTags: ['PropertyGroups'],
		}),

		updatePropertyGroup: builder.mutation<
			PropertyGroup,
			{ id: string; updates: Partial<PropertyGroup> }
		>({
			async queryFn({ id, updates }) {
				try {
					const docRef = doc(db, 'propertyGroups', id);
					await updateDoc(docRef, {
						...updates,
						updatedAt: new Date().toISOString(),
					});
					return { data: { id, ...updates } as PropertyGroup };
				} catch (error: any) {
					return { error: error.message };
				}
			},
			invalidatesTags: ['PropertyGroups'],
		}),

		deletePropertyGroup: builder.mutation<void, string>({
			async queryFn(groupId: string) {
				try {
					await deleteDoc(doc(db, 'propertyGroups', groupId));
					return { data: undefined };
				} catch (error: any) {
					return { error: error.message };
				}
			},
			invalidatesTags: ['PropertyGroups'],
		}),

		// Property endpoints
		getProperties: builder.query<Property[], void>({
			async queryFn() {
				try {
					// Get authenticated user from Firebase Auth
					const currentUser = auth.currentUser;
					if (!currentUser) {
						return { error: 'User not authenticated' };
					}
					const userId = currentUser.uid;

					// Get user's email for shared properties lookup
					const userDocRef = doc(db, 'users', userId);
					const userDoc = await getDoc(userDocRef);
					const userData = userDoc.data();
					const userEmail = userData?.email;
					const normalizedUserEmail = String(userEmail || '')
						.trim()
						.toLowerCase();

					if (
						String(userData?.role || '').trim().toLowerCase() === 'tenant'
					) {
						try {
							const syncTenantAccess = httpsCallable<
								Record<string, never>,
								{ success: boolean }
							>(functions, 'syncTenantAccessFromInvites');
							await syncTenantAccess({});
						} catch (syncError) {
							console.warn('Tenant access sync in getProperties skipped:', syncError);
						}
					}
					const accessibleAccountIds = await resolveAccessibleAccountIds();
					const currentTeamMember = await getTeamMemberForAccountUser(
						accessibleAccountIds,
						userData,
						userId,
						currentUser.email,
					);
					const isTeamMemberScoped = isTeamMemberScopedProfile(
						userData,
						currentTeamMember,
					);

					let tenantInviteProperties: Property[] = [];
					if (normalizedUserEmail) {
						try {
							const tenantInvitesQuery = query(
								collection(db, 'tenantInvitationCodes'),
								where('tenantEmail', '==', normalizedUserEmail),
							);
							const tenantInvitesSnapshot = await getDocs(tenantInvitesQuery);
							const tenantInvitePropertyIds = tenantInvitesSnapshot.docs
								.map((inviteDoc) => inviteDoc.data() as any)
								.filter((invite) => {
									const status = String(invite?.status || '').trim().toLowerCase();
									return (
										(status === 'active' || status === 'redeemed') &&
										typeof invite?.propertyId === 'string' &&
										invite.propertyId.trim().length > 0
									);
								})
								.map((invite) => String(invite.propertyId).trim());

							if (tenantInvitePropertyIds.length > 0) {
								tenantInviteProperties = await fetchPropertiesByIds(
									Array.from(new Set(tenantInvitePropertyIds)),
								);
							}
						} catch (tenantInviteError) {
							console.warn(
								'Could not fetch tenant invite assigned properties:',
								tenantInviteError,
							);
						}
					}

					const accountGroupIds = new Map<string, string[]>();
					for (const accountId of accessibleAccountIds) {
						const groupsQuery = query(
							collection(db, 'propertyGroups'),
							where('accountId', '==', accountId),
						);
						const groupsSnapshot = await getDocs(groupsQuery);
						accountGroupIds.set(
							accountId,
							groupsSnapshot.docs.map((groupDoc) => groupDoc.id),
						);
					}

					const ownedProperties: Property[] = [];
					for (const [accountId, groupIds] of accountGroupIds.entries()) {
						if (groupIds.length === 0) {
							continue;
						}

						// Process in batches of 10 (Firestore limitation)
						for (let i = 0; i < groupIds.length; i += 10) {
							const batch = groupIds.slice(i, i + 10);
							try {
								const propertiesQuery = query(
									collection(db, 'properties'),
									where('accountId', '==', accountId),
									where('groupId', 'in', batch),
								);
								const propertiesSnapshot = await getDocs(propertiesQuery);
								const properties = propertiesSnapshot.docs
									.map((doc) => docToData(doc) as Property)
									.filter(Boolean) as Property[];
								ownedProperties.push(...properties);
							} catch (groupQueryError) {
								console.warn(
									'Could not fetch group-linked properties batch:',
									groupQueryError,
								);
							}
						}
					}

					const accountProperties: Property[] = [];
					for (const accountId of accessibleAccountIds) {
						const accountPropertiesQuery = query(
							collection(db, 'properties'),
							where('accountId', '==', accountId),
						);
						const accountPropertiesSnapshot = await getDocs(
							accountPropertiesQuery,
						);
						const accountPropertiesBatch = accountPropertiesSnapshot.docs
							.map((doc) => docToData(doc) as Property)
							.filter(Boolean) as Property[];
						accountProperties.push(...accountPropertiesBatch);
					}

					// Also fetch properties where user is a co-owner
					let coOwnerProperties: Property[] = [];
					for (const accountId of accessibleAccountIds) {
						try {
							const coOwnerPropertiesQuery = query(
								collection(db, 'properties'),
								where('accountId', '==', accountId),
								where('coOwners', 'array-contains', userId),
							);
							const coOwnerPropertiesSnapshot = await getDocs(
								coOwnerPropertiesQuery,
							);
							const coOwnerPropertiesBatch = coOwnerPropertiesSnapshot.docs
								.map((doc) => docToData(doc) as Property)
								.filter(Boolean) as Property[];
							coOwnerProperties.push(...coOwnerPropertiesBatch);
						} catch (coOwnerError) {
							console.warn('Could not fetch co-owner properties:', coOwnerError);
						}
					}

					// Also fetch properties where user is an administrator
					let adminProperties: Property[] = [];
					for (const accountId of accessibleAccountIds) {
						try {
							const adminPropertiesQuery = query(
								collection(db, 'properties'),
								where('accountId', '==', accountId),
								where('administrators', 'array-contains', userId),
							);
							const adminPropertiesSnapshot = await getDocs(adminPropertiesQuery);
							const adminPropertiesBatch = adminPropertiesSnapshot.docs
								.map((doc) => docToData(doc) as Property)
								.filter(Boolean) as Property[];
							adminProperties.push(...adminPropertiesBatch);
						} catch (adminError) {
							console.warn('Could not fetch admin properties:', adminError);
						}
					}

					// Get shared properties - separate co-owners from regular shares
					const coOwnerSharedProperties: Property[] = [];
					const regularSharedProperties: Property[] = [];
					try {
						const shares = await getReceivedPropertySharesForUser(
							userId,
							userEmail,
							currentUser.email,
						);

						const coOwnerShares = shares.filter(
							(share) => share.permission === 'co-owner',
						);
						const regularShares = shares.filter(
							(share) => share.permission !== 'co-owner',
						);

							// Process co-owner shares (treated as ownership)
							const coOwnerPropertyIds = coOwnerShares.map(
								(share) => share.propertyId,
							);
							if (coOwnerPropertyIds.length > 0) {
								// Process in batches of 10
								for (let i = 0; i < coOwnerPropertyIds.length; i += 10) {
									const batch = coOwnerPropertyIds.slice(i, i + 10);
									const propertiesQuery = query(
										collection(db, 'properties'),
										where('__name__', 'in', batch),
									);
									const propertiesSnapshot = await getDocs(propertiesQuery);
									const properties = propertiesSnapshot.docs
										.map((doc) => docToData(doc) as Property)
										.filter(Boolean) as Property[];
									coOwnerSharedProperties.push(...properties);
								}
							}

							// Process regular shares
							const regularPropertyIds = regularShares.map(
								(share) => share.propertyId,
							);
							if (regularPropertyIds.length > 0) {
								// Process in batches of 10
								for (let i = 0; i < regularPropertyIds.length; i += 10) {
									const batch = regularPropertyIds.slice(i, i + 10);
									const propertiesQuery = query(
										collection(db, 'properties'),
										where('__name__', 'in', batch),
									);
									const propertiesSnapshot = await getDocs(propertiesQuery);
									const properties = propertiesSnapshot.docs
										.map((doc) => docToData(doc) as Property)
										.filter(Boolean) as Property[];
									regularSharedProperties.push(...properties);
								}
							}
					} catch (shareLookupError) {
						console.warn(
							'Could not fetch shared/co-owner properties:',
							shareLookupError,
						);
					}

					// Combine and deduplicate
					const allProperties = [
						...accountProperties,
						...ownedProperties,
						...coOwnerProperties,
						...coOwnerSharedProperties,
						...adminProperties,
						...regularSharedProperties,
						...tenantInviteProperties,
					];
					const uniqueProperties = Array.from(
						new Map(allProperties.map((p) => [p.id, p])).values(),
					);
					const returnedProperties = isTeamMemberScoped
						? scopePropertiesToTeamMember(uniqueProperties, currentTeamMember)
						: uniqueProperties;

					return { data: returnedProperties };
				} catch (error: any) {
					console.error('Error fetching properties:', error.message, error);
					return { error: error.message };
				}
			},
			providesTags: ['Properties'],
		}),

		getProperty: builder.query<Property, string>({
			async queryFn(propertyId: string) {
				try {
					const docRef = doc(db, 'properties', propertyId);
					const docSnapshot = await getDoc(docRef);
					const data = docToData(docSnapshot) as Property;
					return { data };
				} catch (error: any) {
					return { error: error.message };
				}
			},
			providesTags: ['Properties'],
		}),

		createProperty: builder.mutation<Property, Omit<Property, 'id'>>({
			async queryFn(newProperty) {
				try {
					const currentUser = auth.currentUser;
					if (!currentUser) {
						return { error: 'User not authenticated' };
					}
					const targetUserId = await resolveTargetUserId();
					const currentUserDoc = await getDoc(doc(db, 'users', currentUser.uid));
					const currentUserData = currentUserDoc.data() || {};
					const currentTeamMember = await getTeamMemberForAccountUser(
						[targetUserId],
						currentUserData,
						currentUser.uid,
					);

					if (isTeamMemberScopedProfile(currentUserData, currentTeamMember)) {
						return {
							error:
								'Team member accounts cannot create properties. Ask the account owner to add properties and assign access.',
						};
					}

					const ensureFamilyAccountCallable = httpsCallable<
						{
							accountId?: string;
							syncSubscription?: boolean;
							subscription?: Record<string, unknown>;
						},
						{
							id: string;
							subscription?: Record<string, unknown>;
						}
					>(functions, 'ensureFamilyAccount');

					await ensureFamilyAccountCallable({
						accountId: targetUserId,
						syncSubscription: false,
					});

					const accountRef = doc(db, 'familyAccounts', targetUserId);
					const propertyRef = doc(collection(db, 'properties'));

					await runTransaction(db, async (transaction) => {
						const userSnapshot = await transaction.get(
							doc(db, 'users', targetUserId),
						);
						const userData = userSnapshot.data() || {};
						const subscription = userData.subscription || {};
						const planId = subscription.plan || 'home';
						const maxProperties = getMaxPropertiesForPlan(planId);

						const accountSnapshot = await transaction.get(accountRef);
						const accountData = accountSnapshot.data() || {};
						const currentPropertyCount = Number(accountData.propertyCount || 0);

						if (currentPropertyCount >= maxProperties) {
							throw new Error(
								`Property limit reached for current plan (${maxProperties} max).`,
							);
						}

						const nowIso = new Date().toISOString();
						transaction.set(propertyRef, {
							...newProperty,
							userId: targetUserId,
							accountId: targetUserId,
							createdAt: nowIso,
							updatedAt: nowIso,
						});

						transaction.update(accountRef, {
							propertyCount: currentPropertyCount + 1,
							updatedAt: nowIso,
						});
					});

					if (newProperty.groupId) {
						try {
							await upsertPropertyGroupMembership({
								accountId: targetUserId,
								groupId: newProperty.groupId,
								propertyId: propertyRef.id,
								sortOrder: Date.now(),
							});
						} catch (membershipError) {
							console.warn(
								'Property created but group membership update failed:',
								membershipError,
							);
						}
					}

					const savedSnapshot = await getDoc(doc(db, 'properties', propertyRef.id));
					const savedData = docToData(savedSnapshot) as Property;
					return { data: savedData };
				} catch (error: any) {
					return { error: error.message };
				}
			},
			invalidatesTags: ['Properties', 'PropertyGroups'],
		}),

		updateProperty: builder.mutation<
			Property,
			{ id: string; updates: Partial<Property> }
		>({
			async queryFn({ id, updates }) {
				try {
					const docRef = doc(db, 'properties', id);
					const existingSnapshot = await getDoc(docRef);
					const existingData = existingSnapshot.data() || {};
					const accountId =
						String(existingData.accountId || '').trim() ||
						(await resolveTargetUserId());

					await updateDoc(docRef, {
						...updates,
						updatedAt: new Date().toISOString(),
					});

					if ('groupId' in updates) {
						if (updates.groupId) {
							await upsertPropertyGroupMembership({
								accountId,
								groupId: updates.groupId,
								propertyId: id,
							});
						} else {
							await deletePropertyGroupMemberships(id, accountId);
						}
					}

					const savedSnapshot = await getDoc(docRef);
					const savedData = docToData(savedSnapshot) as Property;
					return { data: savedData };
				} catch (error: any) {
					return { error: error.message };
				}
			},
			invalidatesTags: ['Properties', 'PropertyGroups'],
		}),

		deleteProperty: builder.mutation<void, string>({
			async queryFn(propertyId: string) {
				try {
					const currentUser = auth.currentUser;
					if (!currentUser) {
						return { error: 'User not authenticated' };
					}

					const propertyRef = doc(db, 'properties', propertyId);
					const propertySnapshot = await getDoc(propertyRef);
					if (!propertySnapshot.exists()) {
						return { data: undefined };
					}

					const propertyData = propertySnapshot.data() || {};
					const accountId = String(propertyData.accountId || '').trim() || undefined;

					if (accountId) {
						const accountRef = doc(db, 'familyAccounts', accountId);
						await runTransaction(db, async (transaction) => {
							const accountSnapshot = await transaction.get(accountRef);
							const accountData = accountSnapshot.data() || {};
							const currentPropertyCount = Number(accountData.propertyCount || 0);
							const nowIso = new Date().toISOString();

							transaction.delete(propertyRef);
							transaction.update(accountRef, {
								propertyCount: Math.max(0, currentPropertyCount - 1),
								updatedAt: nowIso,
							});
						});
					} else {
						await deleteDoc(propertyRef);
					}

					// Best-effort cleanup: do not fail the mutation if non-critical cleanup
					// lacks permissions in multi-user/shared scenarios.
					if (accountId) {
						try {
							await deletePropertyGroupMemberships(propertyId, accountId);
						} catch (membershipCleanupError) {
							console.warn(
								'Property deleted, but failed to clean up group memberships:',
								membershipCleanupError,
							);
						}
					}

					// Delete only current user's favorites to respect Firestore security
					// rules (users cannot delete other users' favorites from client).
					const favoritesQuery = query(
						collection(db, 'favorites'),
						where('propertyId', '==', propertyId),
						where('userId', '==', currentUser.uid),
					);
					try {
						const favoritesSnapshot = await getDocs(favoritesQuery);
						for (const favDoc of favoritesSnapshot.docs) {
							await deleteDoc(favDoc.ref);
						}
					} catch (favoritesCleanupError) {
						console.warn(
							'Property deleted, but failed to clean up current-user favorites:',
							favoritesCleanupError,
						);
					}

					return { data: undefined };
				} catch (error: any) {
					return { error: error.message };
				}
			},
			invalidatesTags: ['Properties', 'PropertyGroups', 'Favorites'],
		}),

		// Suites endpoints
		getSuites: builder.query<Suite[], string>({
			async queryFn(propertyId: string) {
				try {
					const q = query(
						collection(db, 'suites'),
						where('propertyId', '==', propertyId),
					);
					const querySnapshot = await getDocs(q);
					const suites = querySnapshot.docs.map((doc) => ({
						id: doc.id,
						...doc.data(),
					})) as Suite[];
					return { data: suites };
				} catch (error) {
					return { error: (error as Error).message };
				}
			},
			providesTags: ['Suites'],
		}),

		getSuite: builder.query<Suite, string>({
			async queryFn(suiteId: string) {
				try {
					const docRef = doc(db, 'suites', suiteId);
					const docSnapshot = await getDoc(docRef);
					const data = docToData(docSnapshot) as Suite;
					return { data };
				} catch (error: any) {
					return { error: error.message };
				}
			},
			providesTags: ['Suites'],
		}),

		createSuite: builder.mutation<Suite, Omit<Suite, 'id'>>({
			async queryFn(newSuite) {
				try {
					const currentUser = auth.currentUser;
					if (!currentUser) {
						return { error: 'User not authenticated' };
					}
					const targetUserId = await resolveTargetUserId();
					const docRef = await addDoc(collection(db, 'suites'), {
						...newSuite,
						userId: targetUserId,
						accountId: targetUserId,
						createdAt: new Date().toISOString(),
						updatedAt: new Date().toISOString(),
					});
					return {
						data: {
							id: docRef.id,
							...newSuite,
							userId: targetUserId,
							accountId: targetUserId,
						} as Suite,
					};
				} catch (error: any) {
					return { error: error.message };
				}
			},
			invalidatesTags: ['Suites'],
		}),

		updateSuite: builder.mutation<
			Suite,
			{ id: string; updates: Partial<Suite> }
		>({
			async queryFn({ id, updates }) {
				try {
					const docRef = doc(db, 'suites', id);
					await updateDoc(docRef, {
						...updates,
						updatedAt: new Date().toISOString(),
					});
					const savedSnapshot = await getDoc(docRef);
					const savedData = docToData(savedSnapshot) as Suite;
					return { data: savedData };
				} catch (error: any) {
					return { error: error.message };
				}
			},
			invalidatesTags: ['Suites'],
		}),

		deleteSuite: builder.mutation<void, string>({
			async queryFn(suiteId: string) {
				try {
					await deleteDoc(doc(db, 'suites', suiteId));
					return { data: undefined };
				} catch (error: any) {
					return { error: error.message };
				}
			},
			invalidatesTags: ['Suites'],
		}),

		// Units endpoints
		getUnits: builder.query<Unit[], string>({
			async queryFn(propertyId: string) {
				try {
					if (!propertyId) {
						return { data: [] };
					}
					const accessibleAccountIds = await resolveAccessibleAccountIds();
					const units: Unit[] = [];
					for (const accountId of accessibleAccountIds) {
						const q = query(
							collection(db, 'units'),
							where('accountId', '==', accountId),
							where('propertyId', '==', propertyId),
						);
						const querySnapshot = await getDocs(q);
						const batch = querySnapshot.docs.map(
							(doc) => docToData(doc) as Unit,
						);
						units.push(...batch);
					}

					// First pass: de-dup exact records by document id.
					const uniqueById = Array.from(
						new Map(units.map((unit) => [unit.id, unit])).values(),
					) as Unit[];

					return { data: uniqueById };
				} catch (error) {
					return { error: (error as Error).message };
				}
			},
			providesTags: ['Units'],
		}),

		getUnit: builder.query<Unit, string>({
			async queryFn(unitId: string) {
				try {
					const docRef = doc(db, 'units', unitId);
					const docSnapshot = await getDoc(docRef);
					const data = docToData(docSnapshot) as Unit;
					return { data };
				} catch (error: any) {
					return { error: error.message };
				}
			},
			providesTags: ['Units'],
		}),

		createUnit: builder.mutation<Unit, Omit<Unit, 'id'>>({
			async queryFn(newUnit) {
				try {
					const currentUser = auth.currentUser;
					if (!currentUser) {
						return { error: 'User not authenticated' };
					}
					const targetUserId = await resolveTargetUserId();
					const docRef = await addDoc(collection(db, 'units'), {
						...newUnit,
						userId: targetUserId,
						accountId: targetUserId,
						createdAt: new Date().toISOString(),
						updatedAt: new Date().toISOString(),
					});
					return {
						data: {
							id: docRef.id,
							...newUnit,
							userId: targetUserId,
							accountId: targetUserId,
						} as Unit,
					};
				} catch (error: any) {
					return { error: error.message };
				}
			},
			invalidatesTags: ['Units'],
		}),

		updateUnit: builder.mutation<Unit, { id: string; updates: Partial<Unit> }>({
			async queryFn({ id, updates }) {
				try {
					const docRef = doc(db, 'units', id);
					await updateDoc(docRef, {
						...updates,
						updatedAt: new Date().toISOString(),
					});
					const savedSnapshot = await getDoc(docRef);
					const savedData = docToData(savedSnapshot) as Unit;
					return { data: savedData };
				} catch (error: any) {
					return { error: error.message };
				}
			},
			invalidatesTags: ['Units'],
		}),

		deleteUnit: builder.mutation<void, string>({
			async queryFn(unitId: string) {
				try {
					await deleteDoc(doc(db, 'units', unitId));
					return { data: undefined };
				} catch (error: any) {
					return { error: error.message };
				}
			},
			invalidatesTags: ['Units'],
		}),

		// Get all units across all properties (for reports)
		getAllUnits: builder.query<Unit[], void>({
			async queryFn() {
				try {
					// Get authenticated user from Firebase Auth
					const currentUser = auth.currentUser;
					if (!currentUser) {
						return { error: 'User not authenticated' };
					}
					const accessibleAccountIds = await resolveAccessibleAccountIds();
					const units: Unit[] = [];
					for (const accountId of accessibleAccountIds) {
						const q = query(
							collection(db, 'units'),
							where('accountId', '==', accountId),
						);
						const querySnapshot = await getDocs(q);
						const batch = querySnapshot.docs.map(
							(doc) => docToData(doc) as Unit,
						);
						units.push(...batch);
					}
					const uniqueUnits = Array.from(
						new Map(units.map((unit) => [unit.id, unit])).values(),
					) as Unit[];
					return { data: uniqueUnits };
				} catch (error) {
					return { error: (error as Error).message };
				}
			},
			providesTags: ['Units'],
		}),
	}),
});

